import type { ComponentPropsWithRef, ReactNode } from 'react';

export const AGENT_COMPOSER_DEFAULT_MAX_FILES = 5;
export const AGENT_COMPOSER_DEFAULT_MAX_FILE_SIZE = 10 * 1024 * 1024;
export const AGENT_COMPOSER_DEFAULT_MAX_TOTAL_SIZE = 20 * 1024 * 1024;

export type AgentComposerStatus = 'ready' | 'submitting' | 'streaming' | 'error';

export type AgentComposerMessages = {
	attachAudio: string;
	attachFile: string;
	attachImage: string;
	attachmentsLabel: string;
	audioPreview: (name: string) => string;
	composerLabel: string;
	dropFiles: string;
	fileCountError: (maxFiles: number) => string;
	fileSizeError: (name: string, maxSize: string) => string;
	imagePreview: (name: string) => string;
	placeholder: string;
	removeAttachment: (name: string) => string;
	selectAudio: string;
	selectFile: string;
	selectImage: string;
	send: string;
	stop: string;
	totalSizeError: (maxSize: string) => string;
	unnamedFile: string;
};

export const defaultAgentComposerMessages: AgentComposerMessages = {
	attachAudio: '添加音频',
	attachFile: '添加文件',
	attachImage: '添加图片',
	attachmentsLabel: '附件',
	audioPreview: (name) => `音频预览：${name}`,
	composerLabel: '消息编辑器',
	dropFiles: '松开以添加附件',
	fileCountError: (maxFiles) => `最多添加 ${maxFiles} 个文件。`,
	fileSizeError: (name, maxSize) => `${name} 超过单个文件 ${maxSize} 的限制。`,
	imagePreview: (name) => `图片预览：${name}`,
	placeholder: '输入消息…',
	removeAttachment: (name) => `移除附件：${name}`,
	selectAudio: '选择音频文件',
	selectFile: '选择文件',
	selectImage: '选择图片文件',
	send: '发送',
	stop: '停止生成',
	totalSizeError: (maxSize) => `附件总大小不能超过 ${maxSize}。`,
	unnamedFile: '未命名文件',
};

export function resolveAgentComposerMessages(messages?: Partial<AgentComposerMessages>): AgentComposerMessages {
	return { ...defaultAgentComposerMessages, ...messages };
}

export type AgentComposerLimits = {
	maxFileSize?: number;
	maxFiles?: number;
	maxTotalSize?: number;
};

export type AgentComposerResolvedLimits = {
	maxFileSize: number;
	maxFiles: number;
	maxTotalSize: number;
};

export type AgentComposerErrorCode = 'file-count' | 'file-size' | 'total-size';

export type AgentComposerError = {
	code: AgentComposerErrorCode;
	files: File[];
	message: string;
};

export type AgentComposerSubmitValue = {
	files: File[];
	text: string;
};

export type AgentComposerProps = Omit<ComponentPropsWithRef<'form'>, 'onError' | 'onSubmit'> &
	AgentComposerLimits & {
		accept?: string;
		disabled?: boolean;
		error?: ReactNode;
		files: readonly File[];
		leading?: ReactNode;
		messages?: Partial<AgentComposerMessages>;
		microphone?: ReactNode;
		model?: ReactNode;
		onError?: (error: AgentComposerError) => void;
		onFilesChange: (files: File[]) => void;
		onStop?: () => void;
		onSubmit: (value: AgentComposerSubmitValue) => void;
		onValueChange: (value: string) => void;
		settings?: ReactNode;
		status?: AgentComposerStatus;
		textareaProps?: Omit<ComponentPropsWithRef<'textarea'>, 'disabled' | 'value'>;
		trailing?: ReactNode;
		value: string;
	};

import {
	AGENT_COMPOSER_DEFAULT_MAX_FILE_SIZE,
	AGENT_COMPOSER_DEFAULT_MAX_FILES,
	AGENT_COMPOSER_DEFAULT_MAX_TOTAL_SIZE,
	type AgentComposerError,
	type AgentComposerLimits,
	type AgentComposerMessages,
	type AgentComposerResolvedLimits,
} from './agent-composer-types';

export type AgentComposerFileValidation = {
	accepted: File[];
	errors: AgentComposerError[];
};

export function resolveAgentComposerLimits(limits: AgentComposerLimits): AgentComposerResolvedLimits {
	return {
		maxFiles: boundedInteger(limits.maxFiles, AGENT_COMPOSER_DEFAULT_MAX_FILES),
		maxFileSize: boundedInteger(limits.maxFileSize, AGENT_COMPOSER_DEFAULT_MAX_FILE_SIZE),
		maxTotalSize: boundedInteger(limits.maxTotalSize, AGENT_COMPOSER_DEFAULT_MAX_TOTAL_SIZE),
	};
}

export function validateAgentComposerControlledFiles(
	files: readonly File[],
	limits: AgentComposerResolvedLimits,
	messages: AgentComposerMessages,
): AgentComposerFileValidation {
	return validateAgentComposerFiles([], files, limits, messages);
}

export function validateAgentComposerFiles(
	current: readonly File[],
	incoming: Iterable<File>,
	limits: AgentComposerResolvedLimits,
	messages: AgentComposerMessages,
): AgentComposerFileValidation {
	const accepted: File[] = [];
	const errors: AgentComposerError[] = [];
	const oversized: File[] = [];
	const overCount: File[] = [];
	const overTotal: File[] = [];
	let totalSize = current.reduce((total, file) => total + finiteSize(file.size), 0);
	let count = current.length;

	for (const file of incoming) {
		const size = safeFileSize(file);
		if (size === undefined || size > limits.maxFileSize) {
			oversized.push(file);
			continue;
		}
		if (count >= limits.maxFiles) {
			overCount.push(file);
			continue;
		}
		if (totalSize + size > limits.maxTotalSize) {
			overTotal.push(file);
			continue;
		}
		accepted.push(file);
		count += 1;
		totalSize += size;
	}

	for (const file of oversized) {
		errors.push({
			code: 'file-size',
			files: [file],
			message: messages.fileSizeError(file.name || messages.unnamedFile, formatAgentComposerBytes(limits.maxFileSize)),
		});
	}
	if (overCount.length > 0) {
		errors.push({ code: 'file-count', files: overCount, message: messages.fileCountError(limits.maxFiles) });
	}
	if (overTotal.length > 0) {
		errors.push({
			code: 'total-size',
			files: overTotal,
			message: messages.totalSizeError(formatAgentComposerBytes(limits.maxTotalSize)),
		});
	}
	return { accepted, errors };
}

export function formatAgentComposerBytes(bytes: number): string {
	const size = finiteSize(bytes);
	if (size >= 1024 * 1024) return `${trimNumber(size / (1024 * 1024))} MiB`;
	if (size >= 1024) return `${trimNumber(size / 1024)} KiB`;
	return `${size} B`;
}

function safeFileSize(file: File): number | undefined {
	try {
		return Number.isFinite(file.size) && file.size >= 0 ? Math.floor(file.size) : undefined;
	} catch {
		return undefined;
	}
}

function finiteSize(value: number): number {
	return Number.isFinite(value) ? Math.max(0, Math.floor(value)) : 0;
}

function boundedInteger(value: number | undefined, fallback: number): number {
	return value === undefined || !Number.isFinite(value) ? fallback : Math.max(0, Math.floor(value));
}

function trimNumber(value: number): string {
	return Number.isInteger(value) ? String(value) : value.toFixed(1).replace(/\.0$/, '');
}

'use client';

import { FileText, Music2, X } from 'lucide-react';
import type { ComponentPropsWithRef } from 'react';
import { useEffect, useState } from 'react';
import { cn } from '@/lib/utils';
import { formatAgentComposerBytes } from './agent-composer-files';
import type { AgentComposerMessages } from './agent-composer-types';

export type AgentComposerAttachmentProps = Omit<ComponentPropsWithRef<'li'>, 'children'> & {
	file: File;
	messages: AgentComposerMessages;
	onRemove: () => void;
};

export function AgentComposerAttachment({
	className,
	file,
	messages,
	onRemove,
	...props
}: AgentComposerAttachmentProps) {
	const mediaKind = resolveMediaKind(file.type);
	const objectUrl = useAgentComposerObjectUrl(file, mediaKind !== 'file');
	const name = file.name || messages.unnamedFile;
	return (
		<li
			data-slot='agent-composer-attachment'
			data-media={mediaKind}
			className={cn(
				'border-border bg-background flex min-h-10 max-w-full min-w-0 items-center gap-2 rounded-md border px-2 py-1.5 text-xs',
				className,
			)}
			{...props}
		>
			{mediaKind === 'image' && objectUrl ? (
				<img
					alt={messages.imagePreview(name)}
					className='bg-muted size-8 shrink-0 rounded-sm object-cover'
					height={32}
					src={objectUrl}
					width={32}
				/>
			) : null}
			{mediaKind === 'audio' ? <Music2 aria-hidden='true' className='text-muted-foreground size-4 shrink-0' /> : null}
			{mediaKind === 'file' ? <FileText aria-hidden='true' className='text-muted-foreground size-4 shrink-0' /> : null}
			<div className='min-w-0 flex-1'>
				<div className='truncate font-medium'>{name}</div>
				<div className='text-muted-foreground'>{formatAgentComposerBytes(file.size)}</div>
			</div>
			{mediaKind === 'audio' && objectUrl ? (
				// biome-ignore lint/a11y/useMediaCaption: User-provided previews do not have a transcript track.
				<audio
					aria-label={messages.audioPreview(name)}
					className='h-8 w-40 max-w-[40vw]'
					controls
					preload='metadata'
					src={objectUrl}
				/>
			) : null}
			<button
				type='button'
				className='btn btn-ghost btn-circle btn-xs size-7 min-h-7 min-w-7 shrink-0 p-0'
				aria-label={messages.removeAttachment(name)}
				title={messages.removeAttachment(name)}
				onClick={onRemove}
			>
				<X aria-hidden='true' className='size-3.5' />
			</button>
		</li>
	);
}

function useAgentComposerObjectUrl(file: File, enabled: boolean): string | undefined {
	const [state, setState] = useState<{ file: File; url: string }>();
	useEffect(() => {
		if (!enabled || typeof URL === 'undefined' || typeof URL.createObjectURL !== 'function') {
			setState(undefined);
			return;
		}
		const url = URL.createObjectURL(file);
		setState({ file, url });
		return () => URL.revokeObjectURL(url);
	}, [enabled, file]);
	return state?.file === file ? state.url : undefined;
}

function resolveMediaKind(mediaType: string): 'audio' | 'file' | 'image' {
	if (mediaType.startsWith('image/')) return 'image';
	if (mediaType.startsWith('audio/')) return 'audio';
	return 'file';
}

'use client';

import { FilePlus2, ImagePlus, Music2, Send, Square } from 'lucide-react';
import type { ChangeEvent, ClipboardEvent, CompositionEvent, DragEvent, FormEvent, KeyboardEvent } from 'react';
import { useMemo, useRef, useState } from 'react';
import { cn } from '@/lib/utils';
import { AgentComposerAttachment } from './agent-composer-attachment';
import {
	resolveAgentComposerLimits,
	validateAgentComposerControlledFiles,
	validateAgentComposerFiles,
} from './agent-composer-files';
import type { AgentComposerError, AgentComposerProps } from './agent-composer-types';
import { resolveAgentComposerMessages } from './agent-composer-types';

export function AgentComposer({
	accept,
	className,
	disabled = false,
	error,
	files,
	leading,
	maxFileSize,
	maxFiles,
	maxTotalSize,
	messages,
	microphone,
	model,
	onDragEnter,
	onDragLeave,
	onDragOver,
	onDrop,
	onError,
	onFilesChange,
	onStop,
	onSubmit,
	onValueChange,
	settings,
	status = 'ready',
	textareaProps,
	trailing,
	value,
	...props
}: AgentComposerProps) {
	const copy = resolveAgentComposerMessages(messages);
	const limits = useMemo(
		() => resolveAgentComposerLimits({ maxFileSize, maxFiles, maxTotalSize }),
		[maxFileSize, maxFiles, maxTotalSize],
	);
	const controlledValidation = useMemo(
		() => validateAgentComposerControlledFiles(files, limits, copy),
		[copy, files, limits],
	);
	const validFiles = controlledValidation.accepted;
	const controlledError = controlledValidation.errors.at(-1);
	const [validationError, setValidationError] = useState<AgentComposerError>();
	const [dragActive, setDragActive] = useState(false);
	const composing = useRef(false);
	const imageInput = useRef<HTMLInputElement>(null);
	const audioInput = useRef<HTMLInputElement>(null);
	const fileInput = useRef<HTMLInputElement>(null);
	const busy = status === 'submitting' || status === 'streaming';
	const canSend = !disabled && !busy && (value.trim().length > 0 || validFiles.length > 0);
	const fileEntries = withFileOccurrenceKeys(validFiles);

	function addFiles(incoming: Iterable<File>) {
		if (disabled || busy) return;
		const result = validateAgentComposerFiles(validFiles, incoming, limits, copy);
		for (const issue of result.errors) onError?.(issue);
		setValidationError(result.errors.at(-1));
		if (result.accepted.length > 0) onFilesChange([...files, ...result.accepted]);
	}

	function handleFileChange(event: ChangeEvent<HTMLInputElement>) {
		if (event.currentTarget.files) addFiles(event.currentTarget.files);
		event.currentTarget.value = '';
	}

	function removeFile(file: File) {
		setValidationError(undefined);
		const sourceIndex = files.indexOf(file);
		if (sourceIndex >= 0) onFilesChange(files.filter((_file, current) => current !== sourceIndex));
	}

	function handleSubmit(event: FormEvent<HTMLFormElement>) {
		event.preventDefault();
		if (!canSend) return;
		setValidationError(undefined);
		onSubmit({ text: value, files: [...validFiles] });
	}

	const {
		className: textareaClassName,
		onChange: onTextareaChange,
		onCompositionEnd,
		onCompositionStart,
		onKeyDown,
		onPaste,
		...textareaRest
	} = textareaProps ?? {};

	function handleKeyDown(event: KeyboardEvent<HTMLTextAreaElement>) {
		onKeyDown?.(event);
		if (
			event.defaultPrevented ||
			event.key !== 'Enter' ||
			event.shiftKey ||
			composing.current ||
			event.nativeEvent.isComposing
		) {
			return;
		}
		event.preventDefault();
		if (canSend) event.currentTarget.form?.requestSubmit();
	}

	function handlePaste(event: ClipboardEvent<HTMLTextAreaElement>) {
		onPaste?.(event);
		if (event.defaultPrevented) return;
		const pasted: File[] = [];
		for (const item of event.clipboardData.items) {
			if (item.kind !== 'file') continue;
			const file = item.getAsFile();
			if (file) pasted.push(file);
		}
		if (pasted.length > 0) addFiles(pasted);
	}

	function handleCompositionStart(event: CompositionEvent<HTMLTextAreaElement>) {
		composing.current = true;
		onCompositionStart?.(event);
	}

	function handleCompositionEnd(event: CompositionEvent<HTMLTextAreaElement>) {
		composing.current = false;
		onCompositionEnd?.(event);
	}

	function handleDrop(event: DragEvent<HTMLFormElement>) {
		onDrop?.(event);
		setDragActive(false);
		if (event.defaultPrevented || !event.dataTransfer.types.includes('Files')) return;
		event.preventDefault();
		addFiles(event.dataTransfer.files);
	}

	return (
		<form
			data-slot='agent-composer'
			data-status={status}
			data-drop-active={dragActive ? 'true' : 'false'}
			data-invalid-attachments={controlledError ? 'true' : 'false'}
			aria-busy={busy || undefined}
			aria-label={copy.composerLabel}
			className={cn(
				'border-border bg-background relative flex w-full min-w-0 flex-col rounded-md border shadow-sm',
				disabled && 'opacity-60',
				status === 'error' && 'border-error',
				className,
			)}
			onDragEnter={(event) => {
				onDragEnter?.(event);
				if (!event.defaultPrevented && event.dataTransfer.types.includes('Files')) setDragActive(true);
			}}
			onDragLeave={(event) => {
				onDragLeave?.(event);
				const nextTarget = event.relatedTarget;
				if (!(nextTarget instanceof Node) || !event.currentTarget.contains(nextTarget)) setDragActive(false);
			}}
			onDragOver={(event) => {
				onDragOver?.(event);
				if (!event.defaultPrevented && event.dataTransfer.types.includes('Files')) event.preventDefault();
			}}
			onDrop={handleDrop}
			onSubmit={handleSubmit}
			{...props}
		>
			<input
				ref={imageInput}
				type='file'
				accept='image/*'
				aria-label={copy.selectImage}
				className='sr-only'
				disabled={disabled || busy}
				multiple
				onChange={handleFileChange}
			/>
			<input
				ref={audioInput}
				type='file'
				accept='audio/*'
				aria-label={copy.selectAudio}
				className='sr-only'
				disabled={disabled || busy}
				multiple
				onChange={handleFileChange}
			/>
			<input
				ref={fileInput}
				type='file'
				accept={accept}
				aria-label={copy.selectFile}
				className='sr-only'
				disabled={disabled || busy}
				multiple
				onChange={handleFileChange}
			/>
			{validFiles.length > 0 ? (
				<ul aria-label={copy.attachmentsLabel} className='flex max-h-36 flex-wrap gap-2 overflow-y-auto px-3 pt-3'>
					{fileEntries.map(({ file, key }) => (
						<AgentComposerAttachment key={key} file={file} messages={copy} onRemove={() => removeFile(file)} />
					))}
				</ul>
			) : null}
			<textarea
				aria-label={textareaRest['aria-label'] ?? copy.placeholder}
				className={cn(
					'placeholder:text-muted-foreground field-sizing-content max-h-48 min-h-[4.5rem] w-full resize-none bg-transparent px-3 py-2.5 text-sm outline-none',
					textareaClassName,
				)}
				disabled={disabled}
				placeholder={textareaRest.placeholder ?? copy.placeholder}
				value={value}
				onChange={(event) => {
					onValueChange(event.currentTarget.value);
					onTextareaChange?.(event);
				}}
				onCompositionEnd={handleCompositionEnd}
				onCompositionStart={handleCompositionStart}
				onKeyDown={handleKeyDown}
				onPaste={handlePaste}
				{...textareaRest}
			/>
			{error !== undefined || validationError || controlledError ? (
				<div role='alert' className='text-error px-3 pb-2 text-xs'>
					{error ?? (
						<ul className='space-y-0.5'>
							{validationError ? <li>{validationError.message}</li> : null}
							{controlledValidation.errors.map((issue) => (
								<li key={`${issue.code}:${issue.message}:${issue.files.map(fileIdentity).join('|')}`}>
									{issue.message}
								</li>
							))}
						</ul>
					)}
				</div>
			) : null}
			<div
				data-slot='agent-composer-toolbar'
				className='border-border flex min-h-11 min-w-0 flex-wrap items-center gap-1 border-t px-2 py-1.5'
			>
				{leading}
				<ComposerIconButton
					label={copy.attachImage}
					disabled={disabled || busy}
					onClick={() => imageInput.current?.click()}
				>
					<ImagePlus aria-hidden='true' className='size-4' />
				</ComposerIconButton>
				<ComposerIconButton
					label={copy.attachAudio}
					disabled={disabled || busy}
					onClick={() => audioInput.current?.click()}
				>
					<Music2 aria-hidden='true' className='size-4' />
				</ComposerIconButton>
				<ComposerIconButton
					label={copy.attachFile}
					disabled={disabled || busy}
					onClick={() => fileInput.current?.click()}
				>
					<FilePlus2 aria-hidden='true' className='size-4' />
				</ComposerIconButton>
				{microphone}
				{model}
				{settings}
				<span className='min-w-2 flex-1' />
				{trailing}
				{busy ? (
					<ComposerIconButton label={copy.stop} disabled={disabled || !onStop} className='btn-error' onClick={onStop}>
						<Square aria-hidden='true' className='size-3.5 fill-current' />
					</ComposerIconButton>
				) : (
					<ComposerIconButton label={copy.send} disabled={!canSend} className='btn-primary' submit>
						<Send aria-hidden='true' className='size-4' />
					</ComposerIconButton>
				)}
			</div>
			{dragActive ? (
				<div className='border-primary bg-primary/10 pointer-events-none absolute inset-1 z-10 flex items-center justify-center rounded-md border border-dashed text-sm font-medium'>
					{copy.dropFiles}
				</div>
			) : null}
		</form>
	);
}

function withFileOccurrenceKeys(files: readonly File[]) {
	const occurrences = new Map<string, number>();
	return files.map((file) => {
		const identity = fileIdentity(file);
		const occurrence = occurrences.get(identity) ?? 0;
		occurrences.set(identity, occurrence + 1);
		return { file, key: `${identity}:${occurrence}` };
	});
}

function fileIdentity(file: File) {
	return `${file.webkitRelativePath}:${file.name}:${file.type}:${file.size}:${file.lastModified}`;
}

function ComposerIconButton({
	children,
	className,
	disabled,
	label,
	onClick,
	submit = false,
}: {
	children: import('react').ReactNode;
	className?: string;
	disabled?: boolean;
	label: string;
	onClick?: () => void;
	submit?: boolean;
}) {
	return (
		<button
			type={submit ? 'submit' : 'button'}
			aria-label={label}
			title={label}
			className={cn('btn btn-ghost btn-circle btn-sm size-8 min-h-8 min-w-8 p-0', className)}
			disabled={disabled}
			onClick={onClick}
		>
			{children}
		</button>
	);
}

export * from './agent-composer';
export * from './agent-composer-attachment';
export * from './agent-composer-files';
export * from './agent-composer-types';
